## § ARTIFACT A — `js/search-palette.js` (Ctrl-K palette)

```javascript
/* search-palette.js — Ctrl-K / Cmd-K client-side search palette.
 * Indexes section titles, glyph rows, and defined terms at page-load.
 * Zero runtime dependency; substring+prefix match over in-memory list.
 * Modal is role="dialog" with focus trap + Escape + arrow-key navigation.
 */
(function () {
  'use strict';

  var MAX_RESULTS = 12;
  var palette, input, list, results = [], selected = 0;
  var indexed = null;

  function build() {
    if (indexed) return indexed;
    indexed = [];
    // sections
    document.querySelectorAll('section h2[id], section h3[id]').forEach(function (h) {
      indexed.push({ text: h.textContent.trim(), id: h.id, kind: 'section' });
    });
    // glyph-table rows (if present)
    document.querySelectorAll('#glyph-table tbody tr').forEach(function (tr) {
      var g = tr.querySelector('.glyph-cell, td:first-child');
      var alias = tr.querySelector('.alias-cell, td:nth-child(2)');
      var meaning = tr.querySelector('.meaning-cell, td:last-child');
      if (!g) return;
      indexed.push({
        text: g.textContent.trim() + ' — ' +
              (alias ? alias.textContent.trim() + ' — ' : '') +
              (meaning ? meaning.textContent.trim() : ''),
        id: tr.id || g.textContent.trim(),
        kind: 'glyph'
      });
    });
    // defined terms — <dfn>
    document.querySelectorAll('dfn[id], strong[id]').forEach(function (el) {
      indexed.push({ text: el.textContent.trim(), id: el.id, kind: 'term' });
    });
    return indexed;
  }

  function ensurePalette() {
    if (palette) return palette;
    palette = document.createElement('div');
    palette.id = 'search-palette';
    palette.setAttribute('role', 'dialog');
    palette.setAttribute('aria-modal', 'true');
    palette.setAttribute('aria-label', 'Search');
    palette.hidden = true;
    palette.innerHTML =
      '<div class="sp-backdrop"></div>' +
      '<div class="sp-card">' +
      '  <input id="sp-input" type="search" autocomplete="off" ' +
      '         placeholder="search sections, glyphs, terms…" ' +
      '         aria-label="Search query">' +
      '  <ul id="sp-list" role="listbox"></ul>' +
      '  <div class="sp-hint">↑↓ navigate · Enter jump · Esc close</div>' +
      '</div>';
    document.body.appendChild(palette);
    input = palette.querySelector('#sp-input');
    list = palette.querySelector('#sp-list');
    palette.querySelector('.sp-backdrop').addEventListener('click', close);
    input.addEventListener('input', function () { query(input.value); });
    input.addEventListener('keydown', onKey);
    return palette;
  }

  function score(item, q) {
    var t = item.text.toLowerCase();
    var qi = t.indexOf(q);
    if (qi === -1) return 0;
    // prefix match scores higher
    return qi === 0 ? 100 : (qi < 8 ? 60 : 30);
  }

  function query(raw) {
    var q = (raw || '').trim().toLowerCase();
    if (!q) { results = []; render(); return; }
    var src = build();
    var scored = [];
    for (var i = 0; i < src.length; i++) {
      var s = score(src[i], q);
      if (s > 0) scored.push({ item: src[i], s: s });
    }
    scored.sort(function (a, b) { return b.s - a.s; });
    results = scored.slice(0, MAX_RESULTS).map(function (x) { return x.item; });
    selected = 0;
    render();
  }

  function render() {
    list.innerHTML = '';
    results.forEach(function (r, i) {
      var li = document.createElement('li');
      li.setAttribute('role', 'option');
      li.dataset.id = r.id;
      li.className = 'sp-item sp-' + r.kind + (i === selected ? ' sp-sel' : '');
      li.innerHTML = '<span class="sp-kind">' + r.kind + '</span>' +
                     '<span class="sp-text"></span>';
      li.querySelector('.sp-text').textContent = r.text;
      li.addEventListener('click', function () { jump(r.id); });
      list.appendChild(li);
    });
  }

  function jump(id) {
    close();
    var el = document.getElementById(id);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
      history.replaceState(null, '', '#' + id);
      el.classList.add('sp-flash');
      setTimeout(function () { el.classList.remove('sp-flash'); }, 900);
    }
  }

  function onKey(e) {
    if (e.key === 'Escape') { e.preventDefault(); close(); return; }
    if (e.key === 'ArrowDown') {
      e.preventDefault(); selected = Math.min(selected + 1, results.length - 1); render();
      return;
    }
    if (e.key === 'ArrowUp') {
      e.preventDefault(); selected = Math.max(selected - 1, 0); render(); return;
    }
    if (e.key === 'Enter') {
      e.preventDefault();
      if (results[selected]) jump(results[selected].id);
      return;
    }
  }

  function open() {
    ensurePalette();
    palette.hidden = false;
    document.body.classList.add('sp-open');
    input.value = '';
    results = [];
    render();
    setTimeout(function () { input.focus(); }, 0);
  }

  function close() {
    if (!palette) return;
    palette.hidden = true;
    document.body.classList.remove('sp-open');
  }

  document.addEventListener('keydown', function (e) {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
      e.preventDefault();
      if (palette && !palette.hidden) close(); else open();
    }
  });
})();
```

