## § ARTIFACT D — Build-hash embedding

Append to `scripts/post-build.mjs` (new file):

```javascript
#!/usr/bin/env node
/* post-build.mjs — computes SHA-256 of rendered HTML + inserts into footer data-hash. */
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { join } from 'node:path';

const PAGES = ['index.html', 'CSLv3.html'];
const SHORT = h => h.slice(0, 12);

for (const f of PAGES) {
  const html = readFileSync(f, 'utf8');
  const hash = createHash('sha256').update(html).digest('hex');
  const updated = html.replace(
    /<div class="build-hash" data-hash="[^"]*"[^>]*>[^<]*<\/div>/,
    `<div class="build-hash" data-hash="${hash}">build: sha256:${SHORT(hash)} · ${new Date().toISOString().slice(0,10)}</div>`
  );
  writeFileSync(f, updated);
  console.log(`${f}: sha256:${SHORT(hash)}`);
}
```

Add to `package.json` scripts: `"postbuild": "node scripts/post-build.mjs"`.

